<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import type {Evidence,JsonObject,Task} from '@/domain/types'
import {service} from '@/services/service'
import {ElMessage} from 'element-plus'
import {meetingTopics,emptyMeetingFilters,filterMeetingTopics,rows,text} from './model'
import BusinessTable from './BusinessTable.vue'
import EvidenceLinks from './EvidenceLinks.vue'
const props=defineProps<{data:JsonObject;task:Task}>()
const emit=defineEmits<{source:[evidence:Evidence];detail:[row:JsonObject];refresh:[]}>()
const filter=reactive(emptyMeetingFilters()),applied=ref(emptyMeetingFilters()),filterError=ref(''),active=ref('timeline'),clusterId=ref(''),expanded=ref<string[]>([]),busy=ref(false),question=ref(''),riskPrompt=ref('')
const all=computed(()=>meetingTopics(props.data))
const filtered=computed(()=>filterMeetingTopics(all.value,applied.value).items)
const clusters=computed(()=>{const map=new Map<string,{id:string;name:string;count:number}>();for(const topic of filtered.value){const id=topic.clusterId || '__none';const old=map.get(id);if(old)old.count++;else map.set(id,{id,name:topic.clusterName,count:1})}return [...map.values()].sort((a,b)=>b.count-a.count)})
const groupRows=computed(()=>filtered.value.filter(item=>!clusterId.value || (item.clusterId || '__none')===clusterId.value))
const meetings=computed(()=>{const map=new Map<string,{id:string;date:string;name:string;topics:typeof all.value}>();for(const topic of groupRows.value){if(!map.has(topic.meetingId))map.set(topic.meetingId,{id:topic.meetingId,date:topic.meetingDate,name:topic.meetingName,topics:[]});map.get(topic.meetingId)!.topics.push(topic)}return [...map.values()].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'))})
const unit=computed(()=>{const units=[...new Set(all.value.map(t=>t.unit).filter(Boolean))];return units.length===1 ? units[0] : units.length>1 ? '原文单位，未统一' : '服务未标明单位'})
function apply(){const result=filterMeetingTopics(all.value,filter);filterError.value=result.error;if(!result.error){applied.value={...filter};clusterId.value=''}}
function clear(){Object.assign(filter,emptyMeetingFilters());applied.value=emptyMeetingFilters();filterError.value='';clusterId.value=''}
async function followup(action:'meeting-risk'|'meeting-question'){
 const payload=action==='meeting-risk' ? {prompt:riskPrompt.value} : {question:question.value}
 if(!Object.values(payload).some(v=>v?.trim())){ElMessage.warning(action==='meeting-risk' ? '请填写风险分析提示词' : '请填写问题');return}
 busy.value=true;try{await service.continueTask(props.task,action,payload);emit('refresh')}catch(e){ElMessage.error(e instanceof Error ? e.message : '提交失败')}finally{busy.value=false}
}
</script>
<template><div class="meeting-results"><el-collapse class="filters" :model-value="['filter']"><el-collapse-item title="筛选会议与议题" name="filter"><el-form class="filter-grid" label-position="top" @submit.prevent="apply"><el-form-item label="参会人员"><el-input v-model="filter.participants" placeholder="姓名，多个用逗号分隔" clearable/></el-form-item><el-form-item label="会议日期"><div class="range"><el-input v-model="filter.start" type="date" aria-label="开始日期"/><span>至</span><el-input v-model="filter.end" type="date" aria-label="结束日期"/></div></el-form-item><el-form-item :label="`涉及金额（${unit}）`"><div class="range"><el-input v-model="filter.min" type="number" placeholder="最小金额"/><span>至</span><el-input v-model="filter.max" type="number" placeholder="最大金额"/></div></el-form-item><el-form-item label="议题关键词"><el-input v-model="filter.keyword" placeholder="查找议题名称或内容" clearable/></el-form-item><div class="filter-actions"><el-checkbox v-model="filter.regex">正则匹配</el-checkbox><el-button type="primary" plain native-type="submit">应用筛选</el-button><el-button @click="clear">清空筛选</el-button></div></el-form><el-alert v-if="filterError" :title="filterError" type="error" :closable="false"/></el-collapse-item></el-collapse><div class="meeting-summary"><span><strong>{{meetings.length}}</strong> 场会议</span><span><strong>{{groupRows.length}}</strong> 个议题</span><span><strong>{{clusters.length}}</strong> 个聚类</span><el-tag v-if="clusterId" closable @close="clusterId=''">{{clusters.find(c=>c.id===clusterId)?.name}}</el-tag></div><el-tabs v-model="active"><el-tab-pane label="会议时间轴" name="timeline"/><el-tab-pane label="议题明细" name="details"/><el-tab-pane label="风险分析" name="risks"/><el-tab-pane label="深度问答" name="qa"/></el-tabs><div v-if="['timeline','details'].includes(active)" class="meeting-columns"><aside class="cluster-panel"><h3>议题聚类</h3><button class="cluster-row" :class="{selected:!clusterId}" @click="clusterId=''">全部议题 <strong>{{filtered.length}}</strong></button><button v-for="cluster in clusters" :key="cluster.id" class="cluster-row" :class="{selected:clusterId===cluster.id}" @click="clusterId=cluster.id"><span>{{cluster.name}}</span><strong>{{cluster.count}}</strong></button></aside><section class="meeting-main"><template v-if="active==='timeline'"><div class="timeline-actions"><el-button text type="primary" @click="expanded=meetings.map(m=>m.id)">全部展开</el-button><el-button text type="primary" @click="expanded=[]">全部收起</el-button></div><el-collapse v-model="expanded" class="meeting-timeline"><el-collapse-item v-for="meeting in meetings" :key="meeting.id" :name="meeting.id"><template #title><span class="meeting-date">{{meeting.date || '日期未提取'}}</span><span class="meeting-name">{{meeting.name}}</span><el-tag effect="plain">{{meeting.topics.length}} 个议题</el-tag></template><article v-for="topic in meeting.topics" :key="topic.key" class="topic"><div class="topic-title"><strong>{{topic.topicName}}</strong><el-tag size="small" effect="plain">{{topic.clusterName}}</el-tag></div><p>{{topic.topicContent || '议题内容未返回'}}</p><div class="topic-meta"><span>参会：{{topic.participants.join('、') || '未返回'}}</span><span v-if="topic.amount !== undefined">涉及金额：{{topic.amount}} {{topic.unit}}</span></div><EvidenceLinks :evidence="topic.evidence" @open="emit('source',$event)"/><el-button text type="primary" @click="emit('detail',topic)">议题详情</el-button></article></el-collapse-item></el-collapse><el-empty v-if="!meetings.length" :description="!Array.isArray(data.meetings) ? '服务未返回会议明细，无法生成时间轴' : all.length ? '没有符合筛选条件的会议或议题' : '本次返回的会议议题记录数为 0'"/></template><BusinessTable v-else :rows="groupRows" :columns="['meetingName','meetingDate','topicName','topicContent','participants','amount','unit']" @source="emit('source',$event)" @detail="emit('detail',$event)"/></section></div><section v-else-if="active==='risks'"><BusinessTable v-if="rows(data.risks).length" :rows="rows(data.risks)" @source="emit('source',$event)" @detail="emit('detail',$event)"/><el-empty v-else description="尚未生成会议风险分析结果"/><div v-if="service.capabilities.meetingFollowup" class="followup"><el-form label-position="top"><el-form-item label="风险分析提示词"><el-input v-model="riskPrompt" type="textarea" :rows="5" placeholder="填写本次需要检查的决策程序、资金安排或其他风险"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!all.length || !riskPrompt.trim()" @click="followup('meeting-risk')">开始风险分析</el-button></el-form></div><el-alert v-else title="会议风险分析接口尚未配置；已有结果仍可查看。" type="info" :closable="false"/></section><section v-else><div v-if="data.answers" class="answers">{{text(data.answers)}}</div><el-empty v-else description="围绕会议与议题提出问题，答案应附原文依据"/><el-input v-model="question" type="textarea" :rows="3" placeholder="例如：同一事项在哪些会议中讨论过，决策发生了什么变化？" :disabled="!service.capabilities.meetingFollowup"/><el-button type="primary" :loading="busy" :disabled="!service.capabilities.meetingFollowup || !question.trim()" @click="followup('meeting-question')" class="ask">提问</el-button><p v-if="!service.capabilities.meetingFollowup" class="muted">问答接口尚未配置，暂不能提交新问题。</p></section></div></template>
<style scoped>.filters{border-top:0}.filter-grid{display:grid;grid-template-columns:1fr 1.6fr 1.2fr;gap:0 16px}.range{display:flex;align-items:center;gap:8px;min-width:0}.range .el-input{min-width:0}.filter-actions{display:flex;gap:12px;align-items:center;grid-column:span 2}.meeting-summary{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:14px 0}.meeting-summary strong{font-size:20px;color:#3269db}.meeting-columns{display:grid;grid-template-columns:260px minmax(0,1fr);gap:24px}.cluster-panel{padding-right:18px;border-right:1px solid #e6ebf1}.cluster-panel h3{font-size:16px;margin:0 0 12px}.cluster-row{display:flex;justify-content:space-between;align-items:center;gap:12px;width:100%;padding:12px 10px;background:white;border:0;border-radius:6px;text-align:left;color:#1e3046;cursor:pointer;font:inherit;font-size:14px;margin:3px 0}.cluster-row:hover,.cluster-row.selected{background:#eef4ff;color:#2456b3}.cluster-row strong{font-variant-numeric:tabular-nums}.meeting-main{min-width:0}.timeline-actions{display:flex;justify-content:flex-end}.meeting-date{color:#3269db;white-space:nowrap;margin-right:18px}.meeting-name{flex:1;overflow:hidden;text-overflow:ellipsis;margin-right:12px}.topic{padding:16px 20px;border-left:2px solid #d8e4f8;margin-left:8px}.topic-title{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.topic p{white-space:pre-wrap;line-height:1.8;margin:10px 0}.topic-meta{display:flex;gap:16px;flex-wrap:wrap;color:#596b80;font-size:14px;margin-bottom:8px}.muted{color:#596b80;font-size:14px}.followup{max-width:900px;margin-top:20px}.answers{white-space:pre-wrap;padding:20px;background:#f5f7fa;margin-bottom:16px}.ask{margin-top:12px}@media(max-width:1000px){.filter-grid{grid-template-columns:1fr 1fr}.filter-actions{grid-column:auto}.meeting-columns{grid-template-columns:220px minmax(0,1fr)}}@media(max-width:700px){.filter-grid{grid-template-columns:1fr}.meeting-columns{grid-template-columns:1fr}.cluster-panel{border-right:0;max-height:210px;overflow:auto;border-bottom:1px solid #e6ebf1}.meeting-date{margin-right:8px}.topic{padding:12px}}</style>
